#!/usr/bin/env python3
"""Build the versioned stdin job for the standalone B dynamics analysis.

The new source runs from a temporary directory on the compute node; the existing
frozen checkout supplies environment validation only. Never edits remote code.
Run locally after editing pose_dynamics.py, then review/commit the payload.
"""
from pathlib import Path
import hashlib


PREFIX = '''#!/bin/bash
# Generated by scripts/build_pose_dynamics_payload.py; submit via --script-stdin.
#SBATCH -A IscrB_WearUsFM
#SBATCH -p lrd_all_serial
#SBATCH --nodes=1
#SBATCH --ntasks=1
#SBATCH --cpus-per-task=4
#SBATCH --mem=16G
#SBATCH --time=00:10:00
set -euo pipefail
: "${CODE_DIR:?}" "${EXPECTED_SHA:?}" "${DYN_CACHE:?}" "${DYN_OUT:?}" "${WORK:?}"
: "${DYN_REPORT_PROVENANCE:?}" "${DYN_REFERENCE_REPORT:?}" "${WRAPPER_SHA256:?}"
[ "$EXPECTED_SHA" = 24139ab901c052357a46a65bc20466f2eb1e8358 ] || { echo 'Wrong frozen environment checkout' >&2; exit 2; }
case "$DYN_OUT" in
  /leonardo_work/IscrB_WearUsFM/wearusfm_runs/results/pilot_posa/B5000_student_dynamics_20261028.json) ;;
  *) echo 'Unexpected output destination' >&2; exit 2;;
esac
if [ -e "$DYN_OUT" ]; then echo 'Output already exists' >&2; exit 2; fi
source "$CODE_DIR/scripts/slurm/lib_code_dir.sh"
code_dir_setup
module purge
module load profile/deeplrn
module load cineca-ai/4.3.0
source "$WORK/venv_wearusfm/bin/activate"
export OMP_NUM_THREADS=1 OPENBLAS_NUM_THREADS=1 MKL_NUM_THREADS=1 PYTHONDONTWRITEBYTECODE=1
DYNAMICS_TMP_DIR=$(mktemp -d "${TMPDIR:-/tmp}/wearusfm-b-dynamics.XXXXXX")
DYNAMICS_SOURCE_FILE="$DYNAMICS_TMP_DIR/pose_dynamics.py"
trap 'rm -f -- "$DYNAMICS_SOURCE_FILE"; rmdir -- "$DYNAMICS_TMP_DIR"' EXIT
cat > "$DYNAMICS_SOURCE_FILE" <<'WEARUSFM_DYNAMICS_SOURCE'
'''

SUFFIX = '''WEARUSFM_DYNAMICS_SOURCE
python3 - "$DYNAMICS_SOURCE_FILE" "$DYN_REPORT_PROVENANCE" "$DYN_REFERENCE_REPORT" <<'WEARUSFM_CHECK_HASHES'
from pathlib import Path
import hashlib, sys
checks = [
    (sys.argv[1], "SOURCE_HASH_PLACEHOLDER"),
    (sys.argv[2], "fe619d100b33618e0081fbbc151401d22f4a0dc5f300a2ce164d356f30319c3e"),
    (sys.argv[3], "c3902e4a6095e567115065bc9ec63672f4dea755d21eb5ffc287b57d91d881d9"),
]
for path, expected in checks:
    actual = hashlib.sha256(Path(path).read_bytes()).hexdigest()
    if actual != expected:
        raise SystemExit(f"SHA mismatch for {path}: {actual} != {expected}")
print("Analysis source and reference provenance hashes verified", flush=True)
WEARUSFM_CHECK_HASHES
python3 "$DYNAMICS_SOURCE_FILE" \\
  --cache "$DYN_CACHE" --out "$DYN_OUT" \\
  --expected-cache-sha256 70bb551309b502565d38072abf41ffee322a06de14589d36b720570f1cfbfa46 \\
  --report-provenance "$DYN_REPORT_PROVENANCE" --reference-report "$DYN_REFERENCE_REPORT" \\
  --analysis-source-sha256 SOURCE_HASH_PLACEHOLDER --wrapper-sha256 "$WRAPPER_SHA256"
'''


def build(source: bytes) -> bytes:
    text = source.decode('utf-8')
    if not text.endswith('\n') or '\nWEARUSFM_DYNAMICS_SOURCE\n' in text:
        raise ValueError('Source must end in a newline and not contain the heredoc delimiter')
    digest = hashlib.sha256(source).hexdigest()
    return (PREFIX + text + SUFFIX.replace('SOURCE_HASH_PLACEHOLDER', digest)).encode('utf-8')


if __name__ == '__main__':
    root = Path(__file__).resolve().parents[1]
    source = root / 'scripts/pose_dynamics.py'
    output = root / 'scripts/slurm/pose_dynamics_b.sbatch'
    payload = build(source.read_bytes())
    output.write_bytes(payload)
    print(f'{output}: sha256={hashlib.sha256(payload).hexdigest()}')
